diff --git a/tools/hillink-world/core/initials.mjs b/tools/hillink-world/core/initials.mjs
new file mode 100644
index 0000000..69db203
--- /dev/null
+++ b/tools/hillink-world/core/initials.mjs
@@ -0,0 +1,8 @@
+export function initials(name) {
+  return String(name ?? "")
+    .split(/\s+/)
+    .filter(Boolean)
+    .slice(0, 2)
+    .map((w) => Array.from(w)[0].toUpperCase())
+    .join("");
+}
